#if DEBUG
import Foundation

/// KRI-1582 (`KRIA_CHAT_DESIGN_PICKER=1`, `KRIA_CHAT_DESIGN_PICKER_FIXTURE=<path>`): the design picker end to end.
///
/// The first turn is answered with the server's own design question (`Tests/Fixtures/KRI1582DesignPicker.json`,
/// generated by `tests/kria/test_kri1582_design_picker.py` from the real gate, preview compile and resolver). The
/// answer turn echoes the tapped key and offers the draft. Once the edit is ready its job status carries the rows the
/// resolver draws for the TAPPED design, and an editor Save is kept exactly as the app posted it: the next status
/// (the re-render) serves those rows back, at a new generation.
enum DesignPickerUITestFixture {
    private static let env = ProcessInfo.processInfo.environment
    private static let lock = NSLock()
    nonisolated(unsafe) private static var picked: String?
    nonisolated(unsafe) private static var savedRows: [Any]?
    nonisolated(unsafe) private static var generation = 1

    static var isEnabled: Bool {
        ProcessInfo.processInfo.arguments.contains("-ui-testing-chat") && env["KRIA_CHAT_DESIGN_PICKER"] == "1"
    }

    nonisolated(unsafe) private static let fixture: [String: Any] = {
        guard let path = env["KRIA_CHAT_DESIGN_PICKER_FIXTURE"], let data = FileManager.default.contents(atPath: path),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            preconditionFailure("KRIA_CHAT_DESIGN_PICKER needs KRIA_CHAT_DESIGN_PICKER_FIXTURE (Tests/Fixtures/KRI1582DesignPicker.json)")
        }
        return object
    }()

    static var question: [String: Any] { fixture["question"] as? [String: Any] ?? [:] }
    static var questionText: String { fixture["text"] as? String ?? "" }

    static func recordPick(_ key: String?) {
        lock.lock(); defer { lock.unlock() }
        picked = key
    }

    private static func rows() -> [Any] {
        if let savedRows { return savedRows }
        let designs = fixture["editor_rows"] as? [String: [Any]] ?? [:]
        return designs[picked ?? ""] ?? []
    }

    /// The editor's job status, its source pool (at the same generation) and its Save, for the picker project (its
    /// one variant is the `original_text` the approved job hands the chat); the draft falls through to `PerfFixture`
    /// (`KRIA_EDITOR_FIXTURE=1`).
    static func respond(_ request: URLRequest) -> PerfFixture.Response? {
        guard isEnabled, let path = request.url?.path else { return nil }
        let parts = path.split(separator: "/").map(String.init)
        let method = request.httpMethod ?? "GET"
        lock.lock(); defer { lock.unlock() }
        if method == "GET", parts.count == 3, parts[0] == "generative-jobs", parts[2] == "status", picked != nil {
            let slots: [[String: Any]] = [(4.6, 0), (6.0, 1), (4.6, 2)].map { duration, index in
                ["slot_id": "s\(index)", "clip_index": index, "in_s": 0, "duration_s": 2, "source_duration_s": duration,
                 "removed": false]
            }
            return json(["variants": [[
                "variant_id": "original_text", "render_generation_id": "gen-\(generation)", "render_status": "ready",
                "duration_s": 6.0, "output_url": PerfFixture.editorRenderURL, "resolved_archetype": "montage",
                "editor_capabilities": ["timeline": true, "text_elements": true, "mix": false],
                "user_timeline": ["slots": slots], "text_elements": rows(),
            ] as [String: Any]]])
        }
        if method == "GET", parts.count == 5, parts[0] == "generative-jobs", parts[2] == "variants", parts[4] == "timeline",
           picked != nil {
            let clips: [[String: Any]] = PerfFixture.editorSourceFiles.indices.map { index in
                ["clip_index": index, "native_source": [
                    "media_id": "clip-\(index)", "source_url": "https://\(PerfSourceURLProtocol.host)/clip\(index).mp4",
                    "original": NSNull(), "local_required": false,
                ] as [String: Any]]
            }
            return json(["base_generation": "gen-\(generation)", "clips": clips, "slots": [], "native_assets": []])
        }
        if method == "POST", parts.count == 5, parts[0] == "plan-items", parts[4] == "editor-commit" {
            let body = (try? JSONSerialization.jsonObject(with: bodyData(request))) as? [String: Any] ?? [:]
            guard body["base_generation"] as? String == "gen-\(generation)" else {
                return json(["detail": "baseline_conflict"], status: 409)
            }
            if let posted = body["text_elements"] as? [Any] { savedRows = posted }
            generation += 1
            return json(["ok": true, "generation": "gen-\(generation)", "sections": ["text_elements": true],
                         "revision_number": generation, "revision_hash": "design-picker-\(generation)",
                         "expected_duration_s": 6.0])
        }
        return nil
    }

    private static func json(_ object: Any, status: Int = 200) -> PerfFixture.Response {
        PerfFixture.Response(status: status, data: (try? JSONSerialization.data(withJSONObject: object)) ?? Data())
    }

    private static func bodyData(_ request: URLRequest) -> Data {
        if let data = request.httpBody { return data }
        guard let stream = request.httpBodyStream else { return Data() }
        stream.open(); defer { stream.close() }
        var data = Data(), buffer = [UInt8](repeating: 0, count: 4096)
        while stream.hasBytesAvailable {
            let count = stream.read(&buffer, maxLength: buffer.count)
            if count <= 0 { break }
            data.append(buffer, count: count)
        }
        return data
    }
}
#endif
